/**
 * A coarse shape tag for each move. The battle animation no longer switches
 * on this - MoveAnimationService now composes a per-move effect from the
 * move's real @pkmn/sim data (power, category, multi-hit, flags, status,
 * drain/recoil, weather, target). Archetype is kept as lightweight metadata
 * (grouping, fallbacks, tooling). See scripts/categorize-moves.mjs for the
 * heuristic that assigns it and scripts/move-archetypes.json for the map.
 */
export type MoveArchetype =
  | 'melee' // physical, body-contact attacks (Tackle, Waterfall, Dragon Claw)
  | 'projectile' // thrown/launched objects (Energy Ball, Zap Cannon, Rock Slide)
  | 'beam' // sustained energy stream (Ice Beam, Hyper Beam, Hydro Pump)
  | 'absorb' // life-draining attacks (Giga Drain, Leech Life)
  | 'areal' // wide field/wave effects (Psychic, Dark Pulse, Surf, Earthquake)
  | 'specialAttack' // generic special attacks with no more specific shape (Thunderbolt, Bug Buzz)
  | 'statMove' // non-damaging stat/status moves (Swords Dance, Toxic)
  | 'healMove'; // self-healing moves (Recover, Moonlight, Rest)

/**
 * A move's elemental type (Gen 6 dex: Fairy exists, and Charm / Sweet Kiss are
 * Fairy). Combined with MoveArchetype, this keys the per-(type, archetype) sound
 * lookup - e.g. a "beam" shaped like an Ice attack sounds different from one
 * shaped like a Fire attack.
 */
export type PokemonType =
  | 'Normal'
  | 'Fire'
  | 'Water'
  | 'Electric'
  | 'Grass'
  | 'Ice'
  | 'Fighting'
  | 'Poison'
  | 'Ground'
  | 'Flying'
  | 'Psychic'
  | 'Bug'
  | 'Rock'
  | 'Ghost'
  | 'Dragon'
  | 'Dark'
  | 'Steel'
  | 'Fairy';

export interface Move {
  id: string;
  name: string;
  archetype: MoveArchetype;
  /** The move's elemental type (Gen 6 dex) - see PokemonType. */
  type: PokemonType;
  /** Primary hex color used by the archetype's particles/rings/beam. */
  color: string;
  /**
   * Canonical @pkmn/sim move id (e.g. "solarbeam"). Used both to look up
   * real move data for the damage formula and as the sound file name under
   * assets/sounds/moves/ (see scripts/rename-move-sounds.mjs).
   */
  showdownId: string;
}

